ST.xhtml:
(* ================================================================ *)
(* POU: PRG_Main                                                    *)
(* Implementação                                                     *)
(* ================================================================ *)

(* ================================================================ *)
(* 1. SEGURANÇA GERAL                                               *)
(* ================================================================ *)

g_bEmergencyActive := g_iEmergencyStop;
g_bDoorOpen := g_iSafetyDoor;

IF g_iEmergencyStop OR g_iSafetyDoor THEN
    g_bMachineRunning := FALSE;
ELSE
    IF g_iStop THEN
        g_bMachineRunning := FALSE;
    ELSIF g_iStart AND NOT g_bGeneralFault THEN
        g_bMachineRunning := TRUE;
    END_IF;
END_IF;

(* ================================================================ *)
(* 2. ESCALONAMENTO DAS CÉLULAS DE CARGA                           *)
(* ================================================================ *)

FOR i := 1 TO 4 DO

    rRaw := INT_TO_REAL(g_iWeightRaw[i]);

    IF g_rWeightRawMax > g_rWeightRawMin THEN

        g_rWeightScaled[i] :=
            ((rRaw - g_rWeightRawMin) /
            (g_rWeightRawMax - g_rWeightRawMin)) *
            (g_rWeightEngMax - g_rWeightEngMin) +
            g_rWeightEngMin;

    ELSE
        g_rWeightScaled[i] := g_rWeightEngMin;
    END_IF;

    (* Deslocamento do histórico *)
    FOR j := gc_iFilterSize TO 2 BY -1 DO
        g_rWeightHistory[i, j] :=
            g_rWeightHistory[i, j - 1];
    END_FOR;

    g_rWeightHistory[i, 1] :=
        g_rWeightScaled[i];

    (* Média móvel *)
    rSum := 0.0;

    FOR j := 1 TO gc_iFilterSize DO
        rSum := rSum +
            g_rWeightHistory[i, j];
    END_FOR;

    g_rWeightAverage[i] :=
        rSum / INT_TO_REAL(gc_iFilterSize);

END_FOR;

(* ================================================================ *)
(* 3. ESCALONAMENTO DO NÍVEL DO TANQUE                             *)
(* ================================================================ *)

rRaw := INT_TO_REAL(g_iTankLevelRaw);

IF g_rLevelRawMax > g_rLevelRawMin THEN

    g_rTankLevelScaled :=
        ((rRaw - g_rLevelRawMin) /
        (g_rLevelRawMax - g_rLevelRawMin)) *
        (g_rLevelEngMax - g_rLevelEngMin) +
        g_rLevelEngMin;

ELSE
    g_rTankLevelScaled := g_rLevelEngMin;
END_IF;

(* ================================================================ *)
(* 4. MÉDIA MÓVEL DO NÍVEL DO TANQUE                               *)
(* ================================================================ *)

FOR j := gc_iFilterSize TO 2 BY -1 DO
    g_rTankLevelHistory[j] :=
        g_rTankLevelHistory[j - 1];
END_FOR;

g_rTankLevelHistory[1] :=
    g_rTankLevelScaled;

rSum := 0.0;

FOR j := 1 TO gc_iFilterSize DO
    rSum := rSum +
        g_rTankLevelHistory[j];
END_FOR;

g_rTankLevelAverage :=
    rSum / INT_TO_REAL(gc_iFilterSize);

(* ================================================================ *)
(* 5. CONTROLE DO TANQUE PULMÃO                                    *)
(* ================================================================ *)

IF g_rTankLevelAverage <= gc_rTankLowLevel THEN

    g_qTankFillValve := TRUE;
    g_bTankFilling := TRUE;

ELSIF g_rTankLevelAverage >= gc_rTankHighLevel THEN

    g_qTankFillValve := FALSE;
    g_bTankFilling := FALSE;

END_IF;

IF g_rTankLevelAverage >= gc_rTankLowLevel THEN
    g_bTankReady := TRUE;
ELSE
    g_bTankReady := FALSE;
END_IF;

g_bTankLowAlarm :=
    g_rTankLevelAverage < gc_rTankLowLevel;

IF g_iEmergencyStop OR g_iSafetyDoor THEN
    g_qTankFillValve := FALSE;
    g_bTankFilling := FALSE;
    g_bTankReady := FALSE;
END_IF;

(* ================================================================ *)
(* 6. SELEÇÃO DAS RECEITAS                                         *)
(* ================================================================ *)

(* Exemplo de três receitas em massa *)
g_rRecipeMass[1] := 500.0;
g_rRecipeMass[2] := 750.0;
g_rRecipeMass[3] := 1000.0;

(* A receita somente pode ser alterada com a máquina parada *)
bRecipeChangeAllowed :=
    NOT g_bMachineRunning AND
    NOT g_bCycleActive;

IF bRecipeChangeAllowed THEN

    IF g_iRecipeSelect >= 1 AND
       g_iRecipeSelect <= 3 THEN

        g_iActiveRecipe :=
            g_iRecipeSelect;

    END_IF;
END_IF;

(* ================================================================ *)
(* 7. EXECUÇÃO DAS QUATRO LINHAS                                  *)
(* ================================================================ *)

FOR i := 1 TO 4 DO

    fbLine[i](
        i_bEnable := g_iLineEnable[i],
        i_bStart := g_bMachineRunning,
        i_bStop := g_iStop,
        i_bEmergency := g_iEmergencyStop,
        i_bDoorOpen := g_iSafetyDoor,

        i_bBottlePresent := g_iBottlePresent[i],
        i_bClampExtended := g_iClampExtended[i],
        i_bClampRetracted := g_iClampRetracted[i],

        i_rWeight := g_rWeightAverage[i],
        i_rTargetMass := g_rRecipeMass[g_iActiveRecipe],
        i_bTankReady := g_bTankReady,

        i_bResetFault := g_bAlarmReset
    );

    g_qClampExtend[i] :=
        fbLine[i].q_bClampExtend;

    g_qClampRetract[i] :=
        fbLine[i].q_bClampRetract;

    g_qFillValve[i] :=
        fbLine[i].q_bFillValve;

    g_bLineFault[i] :=
        fbLine[i].q_bFault;

    g_bLineFillTimeout[i] :=
        fbLine[i].q_bFillTimeout;

    g_bLineClampTimeout[i] :=
        fbLine[i].q_bClampTimeout;

    g_bLineBottleRemoved[i] :=
        fbLine[i].q_bBottleRemoved;

END_FOR;

(* ================================================================ *)
(* 8. DIAGNÓSTICO GERAL                                            *)
(* ================================================================ *)

bAnyFault := FALSE;

FOR i := 1 TO 4 DO

    IF g_bLineFault[i] THEN
        bAnyFault := TRUE;
    END_IF;

END_FOR;

g_bGeneralFault :=
    bAnyFault OR
    g_bTankLowAlarm;

IF g_iEmergencyStop OR g_iSafetyDoor THEN
    g_bGeneralFault := FALSE;
END_IF;

(* ================================================================ *)
(* 9. VERIFICAÇÃO DE CONCLUSÃO DO LOTE                             *)
(* ================================================================ *)

bAllComplete := TRUE;

FOR i := 1 TO 4 DO

    IF g_iLineEnable[i] THEN

        IF NOT fbLine[i].q_bComplete THEN
            bAllComplete := FALSE;
        END_IF;

    END_IF;

END_FOR;

(* É necessário que pelo menos uma linha esteja habilitada *)
IF NOT (
    g_iLineEnable[1] OR
    g_iLineEnable[2] OR
    g_iLineEnable[3] OR
    g_iLineEnable[4]
) THEN
    bAllComplete := FALSE;
END_IF;

g_bAllLinesComplete :=
    bAllComplete;

(* ================================================================ *)
(* 10. CONTROLE DO CICLO DO LOTE                                   *)
(* ================================================================ *)

IF g_iEmergencyStop OR g_iSafetyDoor THEN

    g_bCycleActive := FALSE;
    g_bConveyorAdvanceRequest := FALSE;

ELSIF NOT g_bMachineRunning THEN

    g_bCycleActive := FALSE;
    g_bConveyorAdvanceRequest := FALSE;

ELSIF NOT g_bCycleActive THEN

    (* O lote somente começa quando houver garrafas em todas as
       posições habilitadas e a máquina estiver pronta. *)

    bStartCycle := TRUE;

    FOR i := 1 TO 4 DO

        IF g_iLineEnable[i] THEN

            IF NOT g_iBottlePresent[i] THEN
                bStartCycle := FALSE;
            END_IF;

        END_IF;

    END_FOR;

    IF bStartCycle AND g_bTankReady THEN
        g_bCycleActive := TRUE;
    END_IF;

END_IF;

(* ================================================================ *)
(* 11. AVANÇO DA ESTEIRA                                           *)
(* ================================================================ *)

IF g_bCycleActive AND
   g_bAllLinesComplete AND
   NOT g_bGeneralFault THEN

    g_bConveyorAdvanceRequest := TRUE;

ELSE

    g_bConveyorAdvanceRequest := FALSE;

END_IF;

(* ================================================================ *)
(* 12. MOVIMENTO DA ESTEIRA                                        *)
(* ================================================================ *)

IF g_bConveyorAdvanceRequest AND
   NOT g_iEmergencyStop AND
   NOT g_iSafetyDoor THEN

    g_qConveyorRun := TRUE;

    tonConveyorAdvance(
        IN := TRUE,
        PT := T#2s
    );

    IF tonConveyorAdvance.Q THEN

        g_qConveyorRun := FALSE;
        tonConveyorAdvance(IN := FALSE);

        g_bCycleActive := FALSE;
        g_bConveyorAdvanceRequest := FALSE;

    END_IF;

ELSE

    g_qConveyorRun := FALSE;
    tonConveyorAdvance(IN := FALSE);

END_IF;

(* ================================================================ *)
(* 13. CONTAGEM DE GARRAFAS ENVASADAS                              *)
(* ================================================================ *)

bCountCompleteEdge :=
    g_bAllLinesComplete AND
    NOT bPreviousAllComplete;

IF bCountCompleteEdge THEN

    FOR i := 1 TO 4 DO

        IF g_iLineEnable[i] AND
           fbLine[i].q_bComplete THEN

            g_udFilledBottles :=
                g_udFilledBottles + 1;

        END_IF;

    END_FOR;

END_IF;

bPreviousAllComplete :=
    g_bAllLinesComplete;

(* ================================================================ *)
(* 14. CONTAGEM DE REJEITADAS                                      *)
(* ================================================================ *)

bRejectCycle := FALSE;

FOR i := 1 TO 4 DO

    IF g_bLineFault[i] THEN
        bRejectCycle := TRUE;
    END_IF;

END_FOR;

bCountRejectEdge :=
    bRejectCycle AND
    NOT bRejectCycle;

IF bCountRejectEdge THEN
    g_udRejectedBottles :=
        g_udRejectedBottles + 1;
END_IF;

(* ================================================================ *)
(* 15. SOBREPOSIÇÃO FINAL DE SEGURANÇA                             *)
(* ================================================================ *)

IF g_iEmergencyStop OR g_iSafetyDoor THEN

    g_qConveyorRun := FALSE;
    g_qTankFillValve := FALSE;

    FOR i := 1 TO 4 DO

        g_qClampExtend[i] := FALSE;
        g_qClampRetract[i] := FALSE;
        g_qFillValve[i] := FALSE;

    END_FOR;

END_IF;

(* ================================================================ *)
(* POU: FB_Line                                                     *)
(* Implementação                                                     *)
(* ================================================================ *)

(* --------------------------------------------------------------- *)
(* Prioridade máxima: emergência e porta de proteção               *)
(* --------------------------------------------------------------- *)

IF i_bEmergency OR i_bDoorOpen THEN

    q_bClampExtend := FALSE;
    q_bClampRetract := FALSE;
    q_bFillValve := FALSE;

    xRun := FALSE;
    q_iState := gc_iLineWaitBottle;

ELSE

    (* ----------------------------------------------------------- *)
    (* Reset de falha                                               *)
    (* ----------------------------------------------------------- *)

    IF i_bResetFault THEN
        q_bFault := FALSE;
        q_bFillTimeout := FALSE;
        q_bClampTimeout := FALSE;
        q_bBottleRemoved := FALSE;

        IF q_iState = gc_iLineFault THEN
            q_iState := gc_iLineWaitBottle;
        END_IF;
    END_IF;

    (* ----------------------------------------------------------- *)
    (* Linha desabilitada                                           *)
    (* ----------------------------------------------------------- *)

    IF NOT i_bEnable THEN

        q_bClampExtend := FALSE;
        q_bClampRetract := TRUE;
        q_bFillValve := FALSE;

        q_bComplete := FALSE;
        xRun := FALSE;

        q_iState := gc_iLineDisabled;

    ELSE

        (* ------------------------------------------------------- *)
        (* Parada                                                   *)
        (* ------------------------------------------------------- *)

        IF i_bStop THEN

            q_bClampExtend := FALSE;
            q_bClampRetract := TRUE;
            q_bFillValve := FALSE;

            xRun := FALSE;
            q_bComplete := FALSE;

            q_iState := gc_iLineWaitBottle;

        ELSE

            (* --------------------------------------------------- *)
            (* Máquina de estados                                   *)
            (* --------------------------------------------------- *)

            CASE q_iState OF

                gc_iLineDisabled:
                    q_bClampExtend := FALSE;
                    q_bClampRetract := TRUE;
                    q_bFillValve := FALSE;
                    q_bComplete := FALSE;

                    q_iState := gc_iLineWaitBottle;


                gc_iLineWaitBottle:

                    q_bClampExtend := FALSE;
                    q_bClampRetract := TRUE;
                    q_bFillValve := FALSE;
                    q_bComplete := FALSE;

                    tonBottleDetect(
                        IN := NOT i_bBottlePresent,
                        PT := gc_tBottleDetectTimeout
                    );

                    IF i_bStart AND i_bBottlePresent AND i_bTankReady THEN
                        tonBottleDetect(IN := FALSE);
                        q_iState := gc_iLineClamp;
                    END_IF;

                    IF tonBottleDetect.Q THEN
                        tonBottleDetect(IN := FALSE);
                    END_IF;


                gc_iLineClamp:

                    q_bClampExtend := TRUE;
                    q_bClampRetract := FALSE;
                    q_bFillValve := FALSE;

                    tonClamp(
                        IN := NOT i_bClampExtended,
                        PT := gc_tClampTimeout
                    );

                    IF i_bClampExtended THEN
                        tonClamp(IN := FALSE);
                        q_iState := gc_iLineFilling;
                    END_IF;

                    IF tonClamp.Q THEN
                        q_bClampTimeout := TRUE;
                        q_bFault := TRUE;
                        q_iState := gc_iLineFault;
                    END_IF;


                gc_iLineFilling:

                    q_bClampExtend := TRUE;
                    q_bClampRetract := FALSE;

                    (* A válvula somente pode abrir com tanque disponível *)
                    q_bFillValve := i_bTankReady;

                    tonFill(
                        IN := TRUE,
                        PT := gc_tFillTimeout
                    );

                    (* A garrafa não pode desaparecer durante o enchimento *)
                    IF NOT i_bBottlePresent THEN
                        q_bFillValve := FALSE;
                        q_bBottleRemoved := TRUE;
                        q_bFault := TRUE;
                        q_iState := gc_iLineFault;

                    ELSIF i_rWeight >= i_rTargetMass THEN
                        q_bFillValve := FALSE;
                        tonFill(IN := FALSE);
                        q_iState := gc_iLineDrip;

                    ELSIF tonFill.Q THEN
                        q_bFillValve := FALSE;
                        q_bFillTimeout := TRUE;
                        q_bFault := TRUE;
                        q_iState := gc_iLineFault;
                    END_IF;


                gc_iLineDrip:

                    q_bClampExtend := TRUE;
                    q_bClampRetract := FALSE;
                    q_bFillValve := FALSE;

                    tonDrip(
                        IN := TRUE,
                        PT := gc_tDripTime
                    );

                    IF tonDrip.Q THEN
                        tonDrip(IN := FALSE);
                        q_iState := gc_iLineRelease;
                    END_IF;


                gc_iLineRelease:

                    q_bClampExtend := FALSE;
                    q_bClampRetract := TRUE;
                    q_bFillValve := FALSE;

                    tonRelease(
                        IN := NOT i_bClampRetracted,
                        PT := gc_tReleaseTimeout
                    );

                    IF i_bClampRetracted THEN
                        tonRelease(IN := FALSE);
                        q_iState := gc_iLineComplete;
                    END_IF;

                    IF tonRelease.Q THEN
                        q_bClampTimeout := TRUE;
                        q_bFault := TRUE;
                        q_iState := gc_iLineFault;
                    END_IF;


                gc_iLineComplete:

                    q_bClampExtend := FALSE;
                    q_bClampRetract := TRUE;
                    q_bFillValve := FALSE;

                    q_bComplete := TRUE;

                    IF NOT i_bBottlePresent THEN
                        q_bComplete := FALSE;
                        q_iState := gc_iLineWaitBottle;
                    END_IF;


                gc_iLineFault:

                    q_bClampExtend := FALSE;
                    q_bClampRetract := TRUE;
                    q_bFillValve := FALSE;

                    q_bComplete := FALSE;
                    xRun := FALSE;


                ELSE

                    q_bClampExtend := FALSE;
                    q_bClampRetract := TRUE;
                    q_bFillValve := FALSE;

                    q_bComplete := FALSE;
                    q_iState := gc_iLineWaitBottle;

            END_CASE;

        END_IF;
    END_IF;
END_IF;

(* --------------------------------------------------------------- *)
(* Atualização dos temporizadores fora das transições críticas     *)
(* --------------------------------------------------------------- *)

IF q_iState <> gc_iLineClamp THEN
    tonClamp(IN := FALSE);
END_IF;

IF q_iState <> gc_iLineFilling THEN
    tonFill(IN := FALSE);
END_IF;

IF q_iState <> gc_iLineDrip THEN
    tonDrip(IN := FALSE);
END_IF;

IF q_iState <> gc_iLineRelease THEN
    tonRelease(IN := FALSE);
END_IF;
